script:
const reviewForm = document.getElementById("review_form");
const starSvg = reviewForm.querySelector("svg");
const stars = starSvg.querySelectorAll("path"); 

let ratingInput = reviewForm.querySelector('input[name="rating"]');
if (!ratingInput) {
  ratingInput = document.createElement("input");
  ratingInput.type = "hidden";
  ratingInput.name = "rating";
  ratingInput.value = 0;
  reviewForm.appendChild(ratingInput);
}

function fillStars(selectedIndex) {
  stars.forEach((star, index) => {
    if (index <= selectedIndex) {
      star.setAttribute("stroke", "#F49F00"); 
      star.setAttribute("fill", "#F49F00");  
    } else {
      star.setAttribute("stroke", "#F49F00");
      star.setAttribute("fill", "none");
    }
  });
  // Store as fraction of total stars
  ratingInput.value = ((selectedIndex + 1) / stars.length).toFixed(1); 
}

stars.forEach((star, index) => {
  star.style.cursor = "pointer";

  star.addEventListener("click", () => fillStars(index));

  // Hover preview
  star.addEventListener("mouseenter", () => fillStars(index));
  star.addEventListener("mouseleave", () => {
    const currentRating = parseFloat(ratingInput.value) || 0;
    fillStars(Math.round(currentRating * stars.length) - 1);
  });
});

reviewForm.addEventListener("submit", async (e) => {
  e.preventDefault();

  const formData = new FormData(reviewForm);

  const CSRF_TOKEN = page_data.csrf_token
  const HEADERS = {
    "x-frappe-csrf-token": CSRF_TOKEN,
    "x-requested-with": "XMLHttpRequest",
    Accept: "application/json, text/javascript, */*; q=0.01"
  }

  try {
    const response = await fetch("/api/method/invento_webshop.api.item.submit_review", {
      method: "POST",
      headers: HEADERS,
      body: formData
    });

    const result = await response.json();
    console.log(result)
    if (result.message){
      console.log("Review submitted:", result);

    reviewForm.reset();
    fillStars(-1);

	Toastify({
      text: "Review submitted successfully!",
      close: true,
      gravity: "top",
      position: "center",
      stopOnFocus: true,
    }).showToast();
    window.location.reload()
    }
    else{

    // Parse Frappe _server_messages if available
    let message = "Failed to submit review.";
    if (result && result._server_messages) {
  try {
    // Step 1: parse the outer JSON array
    const serverMessagesArray = JSON.parse(result._server_messages);

    // Step 2: parse each inner JSON string
    const messages = serverMessagesArray.map(msgStr => {
      try {
        return JSON.parse(msgStr).message;
      } catch (e) {
        console.warn("Could not parse individual server message", e);
        return null;
      }
    }).filter(Boolean); // remove nulls

    if (messages.length > 0) {
      // Combine all messages, use <br> if showing in modal
      message = messages.join("<br><br>");
    }

  } catch (e) {
    console.warn("Could not parse _server_messages", e);
  }
}

    Toastify({
      text: message,
      close: true,
      gravity: "top",
      position: "center",
      stopOnFocus: true,
      style: {
        background: "linear-gradient(to right, #ff416c, #ff4b2b)",
      }
    }).showToast();
    }
  }catch (error) {

  }
});

document.addEventListener('DOMContentLoaded', function() {
    // 1. Load Swiper CSS
    const link = document.createElement('link');
    link.rel = 'stylesheet';
    link.href = 'https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.css';
    document.head.appendChild(link);
    // 2. Load Swiper JS
    const script = document.createElement('script');
    script.src = 'https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.js';
    script.onload = initSliders;
    document.head.appendChild(script);
    function initSliders() {
        // Configuration for each slider type
        const sliderConfigs = [
            { selector: '[id="related-products"]', slidesPerView: { 640: 2, 768: 3, 1024: 5 } },
        ];
        sliderConfigs.forEach(config => {
            // Use querySelectorAll to find ALL blocks with the matching ID
            // This handles cases where IDs might be duplicated in the builder
            const containers = document.querySelectorAll(config.selector);

            containers.forEach(container => {
                // Initialize slider if it hasn't been initialized yet
                if (!container.classList.contains('swiper-initialized')) {
                    initSingleSlider(container, config);
                }
            });
        });
    }
    function initSingleSlider(container, config) {
        // Check if the container has children to slide
        if (container.children.length === 0) {
            return;
        }
        // 4. Prepare the DOM for Swiper
        container.classList.add('swiper');

        // Reset styles that might interfere with Swiper
        container.style.display = 'block';
        container.style.gridTemplateColumns = 'none';
        container.style.gap = '0';
        container.style.overflow = 'hidden'; // Important for Swiper
        // Create wrapper
        const wrapper = document.createElement('div');
        wrapper.classList.add('swiper-wrapper');
        // Move all children (slides) into the wrapper
        while (container.firstChild) {
            const child = container.firstChild;
            // Ensure child is an element node
            if (child.nodeType === 1) {
                child.classList.add('swiper-slide');
                // Reset child styles if necessary
                child.style.height = 'auto'; 
                child.style.width = 'auto'; // Let Swiper handle width
            }
            wrapper.appendChild(child);
        }
        container.appendChild(wrapper);
        // 5. Initialize Swiper
        new Swiper(container, {
            slidesPerView: 1,
            spaceBetween: 20,
            speed: 1600,
            loop: true,
            autoplay: {
                delay: 4200,
                disableOnInteraction: false,
            },
            breakpoints: {
                640: {
                    slidesPerView: config.slidesPerView[640],
                    spaceBetween: 20,
                },
                768: {
                    slidesPerView: config.slidesPerView[768],
                    spaceBetween: 30,
                },
                1024: {
                    slidesPerView: config.slidesPerView[1024],
                    spaceBetween: 30,
                },
            },
            navigation: {
              nextEl: '.swiper-next',
              prevEl: '.swiper-prev',
            },
        });
    }
});
